import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def count_good_partitions(a):
    n = len(a)
    if n < 2:
        return 0

    count = 0
    for k in range(1, n):
        A_k = a[:k]
        B_k = a[k:]

        L_k = list_lcm(A_k)
        G_k = list_gcd(B_k)

        if L_k == G_k:
            count += 1

    return count

